function launchWorker(reason) {
  if (starting) return;
  const now = Date.now();
  if ((now - lastStart) < START_GRACE_MS) return;

  const dir = workerPath();
  if (!dir) {
    if (!missingPathWarned) {
      console.error(`[${RESOURCE}] ai_dispatch_worker_path is not set. Add the worker path to server.cfg.`);
      missingPathWarned = true;
    }
    return;
  }

  const script = path.join(dir, 'restart-worker.ps1');
  starting = true;
  lastStart = now;
  console.log(`[${RESOURCE}] Worker offline (${reason}); starting AI dispatch worker from configured path...`);

  try {
    const child = spawn('powershell.exe', [
      '-NoProfile',
      '-ExecutionPolicy', 'Bypass',
      '-File', script
    ], {
      cwd: dir,
      windowsHide: true,
      detached: true,
      stdio: 'ignore'
    });

    child.once('error', (err) => {
      console.error(`[${RESOURCE}] Worker launch failed: ${err && err.message ? err.message : err}`);
      console.error(`[${RESOURCE}] Confirm server.cfg contains: add_unsafe_child_process_permission "${RESOURCE}"`);
      starting = false;
    });

    child.unref();
  } catch (err) {
    console.error(`[${RESOURCE}] Failed to launch worker: ${err && err.message ? err.message : err}`);
    console.error(`[${RESOURCE}] Confirm server.cfg contains: add_unsafe_child_process_permission "${RESOURCE}"`);
    starting = false;
  }

  setTimeout(() => { starting = false; }, START_GRACE_MS);
}

